@import url("https://fonts.googleapis.com/css2?family=Titillium+Web:wght@400;600;700;900&display=swap");
:root{--blue:#0052FF;--blue-d:#003CC0;--blue-l:#EAF0FF;--yel:#FFD400;--ink:#0B0F1A;--text:#1B2230;--muted:#667085;--line:#E4E8EF;--bg:#F5F7FB;--red:#E0312B;
--font:"Titillium Web",system-ui,-apple-system,"Segoe UI",sans-serif;--wrap:1260px}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font);font-size:17px;line-height:1.55;color:var(--text);background:#fff;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}a{color:inherit}p{margin:0 0 1em}
h1,h2,h3{margin:0;line-height:1.05;color:var(--ink);font-weight:900;letter-spacing:-.01em}h3{font-weight:700}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--yel);padding:10px;z-index:99}
:focus-visible{outline:3px solid var(--yel);outline-offset:2px;border-radius:4px}
.topbar{background:var(--ink);color:#C9D1E0;font-size:14px}.topbar .wrap{display:flex;justify-content:space-between;gap:12px;padding-top:7px;padding-bottom:7px;flex-wrap:wrap}
.site-header{background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:40}
.nav{display:flex;align-items:center;gap:22px;height:70px}
.logo{font-weight:900;font-size:26px;text-decoration:none;color:var(--ink);display:flex;align-items:center;gap:6px}.logo i{color:var(--blue);font-style:normal}
.search{flex:1;display:flex;border:2px solid var(--blue);border-radius:10px;overflow:hidden;max-width:560px}
.search input{flex:1;border:0;padding:10px 14px;font:inherit;min-width:0}.search input:focus{outline:none}
.search button{background:var(--blue);color:#fff;border:0;padding:0 18px;font:inherit;font-weight:700;cursor:pointer}
.acts{display:flex;gap:16px;margin-left:auto;align-items:center;font-weight:600}
.acts a{text-decoration:none}.cartb{background:var(--blue-l);color:var(--blue);border-radius:10px;padding:8px 14px}
.cats-bar{background:#fff;border-bottom:1px solid var(--line)}
.cats-bar ul{display:flex;gap:26px;list-style:none;margin:0;padding:0;overflow-x:auto;white-space:nowrap}
.cats-bar a{display:block;padding:12px 0;text-decoration:none;font-weight:600;color:var(--muted)}.cats-bar a:hover{color:var(--blue)}
.burger{display:none;background:none;border:1px solid var(--line);border-radius:8px;padding:6px 10px;cursor:pointer}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:13px 24px;border-radius:10px;font-weight:700;text-decoration:none;border:0;font-family:var(--font);font-size:17px;cursor:pointer}
.btn-y{background:var(--yel);color:var(--ink)}.btn-b{background:var(--blue);color:#fff}.btn-b:hover{background:var(--blue-d)}
.hero{padding:26px 0}
.hero-grid{display:grid;grid-template-columns:2fr 1fr;gap:18px}
.banner{background:var(--blue);border-radius:22px;color:#DDE6FF;display:grid;grid-template-columns:1fr 1fr;overflow:hidden;min-height:400px}
.banner .c{padding:44px}.banner small{background:var(--yel);color:var(--ink);font-weight:700;border-radius:6px;padding:3px 10px}
.banner h1{color:#fff;font-size:clamp(38px,4.6vw,62px);margin:16px 0}.banner p{font-size:18px;margin-bottom:24px}
.banner .pr{font-size:40px;font-weight:900;color:#fff}.banner .pr s{font-size:20px;opacity:.7;margin-left:10px}
.banner img{width:100%;height:100%;object-fit:cover}
.side-b{display:grid;gap:18px}
.mini{border-radius:22px;padding:24px;position:relative;overflow:hidden;min-height:190px;display:flex;flex-direction:column;justify-content:flex-end}
.mini img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.mini::after{content:"";position:absolute;inset:0;background:linear-gradient(transparent 30%,rgba(11,15,26,.85))}
.mini div{position:relative;z-index:1;color:#fff}.mini h2{color:#fff;font-size:26px}.mini a{color:var(--yel);font-weight:700}
.trust{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:18px}
.trust div{background:var(--bg);border-radius:14px;padding:16px;font-size:15px}.trust b{display:block;color:var(--ink)}
section{padding:60px 0}
.head{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px;flex-wrap:wrap}
.head h2{font-size:clamp(30px,3.4vw,42px)}
.deal{background:var(--ink);border-radius:22px;padding:30px;color:#C9D1E0}
.deal .head h2{color:#fff}
.timer{display:flex;gap:8px;align-items:center;font-weight:700}
.timer span{background:var(--yel);color:var(--ink);border-radius:8px;padding:6px 10px;font-size:22px;font-weight:900;min-width:50px;text-align:center}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:14px;display:flex;flex-direction:column;position:relative}
.card figure{margin:0 0 12px;border-radius:12px;overflow:hidden;background:var(--bg);aspect-ratio:1/1}
.card img{width:100%;height:100%;object-fit:cover}
.card .off{position:absolute;top:22px;left:22px;background:var(--red);color:#fff;font-weight:700;font-size:13px;border-radius:6px;padding:2px 8px}
.card h3{font-size:17px;font-weight:600;color:var(--text);margin-bottom:4px}
.card .rt{font-size:14px;color:var(--muted)}.card .rt b{color:#F5A000}
.card .pr{font-size:22px;font-weight:900;color:var(--ink);margin:8px 0}.card .pr s{font-size:15px;font-weight:400;color:var(--muted);margin-left:6px}
.card .row{display:flex;gap:8px;margin-top:auto;align-items:center}
.card .row .btn{flex:1;padding:10px;font-size:15px}
.cmp{display:flex;align-items:center;gap:6px;font-size:14px;color:var(--muted);cursor:pointer}
.cmp input{accent-color:var(--blue)}
.cats{display:grid;grid-template-columns:repeat(6,1fr);gap:14px}
.cat{background:var(--bg);border-radius:18px;padding:22px 14px;text-align:center;text-decoration:none;font-weight:700}
.cat span{font-size:34px;display:block;margin-bottom:8px}.cat small{display:block;font-weight:400;color:var(--muted)}
.cat:hover{background:var(--blue-l);color:var(--blue)}
.brands{display:flex;justify-content:space-between;gap:30px;flex-wrap:wrap;padding:30px 0;border-block:1px solid var(--line)}
.brands span{font-weight:900;font-size:24px;color:#A7B0C0;letter-spacing:.02em}
.faq{max-width:860px}
.faq details{border:1px solid var(--line);border-radius:14px;padding:16px 20px;margin-bottom:10px}
.faq summary{list-style:none;cursor:pointer;font-weight:700;font-size:18px;display:flex;justify-content:space-between;gap:16px}
.faq summary::-webkit-details-marker{display:none}.faq summary::after{content:"+";color:var(--blue);font-size:22px;line-height:1}.faq details[open] summary::after{content:"−"}
.faq details p{margin:10px 0 0;color:var(--muted)}
.cbar{position:fixed;left:50%;bottom:20px;transform:translate(-50%,140%);background:var(--ink);color:#fff;border-radius:14px;padding:12px 16px;display:flex;gap:14px;align-items:center;z-index:60;transition:transform .3s;box-shadow:0 20px 40px rgba(0,0,0,.3)}
.cbar.show{transform:translate(-50%,0)}
footer{background:var(--ink);color:#98A2B3;padding:50px 0 26px;font-size:15px}
.foot{display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:30px;margin-bottom:30px}
footer .logo{color:#fff}footer h3{color:#fff;font-size:16px;margin-bottom:10px}footer ul{list-style:none;padding:0;margin:0}footer li{margin-bottom:6px}footer a{text-decoration:none}footer a:hover{color:#fff}
.legal{border-top:1px solid #1F2636;padding-top:16px;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}
@media (max-width:1050px){.hero-grid{grid-template-columns:1fr}.side-b{grid-template-columns:1fr 1fr}.grid{grid-template-columns:repeat(3,1fr)}.cats{grid-template-columns:repeat(3,1fr)}.foot{grid-template-columns:1fr 1fr}}
@media (max-width:760px){.search{display:none}.banner{grid-template-columns:1fr}.banner img{height:260px}.grid{grid-template-columns:1fr 1fr}.trust{grid-template-columns:1fr 1fr}.acts .lbl{display:none}}
@media (max-width:480px){.side-b{grid-template-columns:1fr}.cats{grid-template-columns:1fr 1fr}.banner .c{padding:28px}.grid{gap:10px}.card .row{flex-direction:column;align-items:stretch}}

