const card=(p,k)=>`<article class="card">${p[3]?`<span class="off">−${Math.round((1-p[2]/p[3])*100)}%</span>`:''}<figure><img src="https://images.unsplash.com/photo-${p[1]}?w=500&h=500&q=75&auto=format&fit=crop" alt="${p[0]}" width="500" height="500" loading="lazy"></figure><h3>${p[0]}</h3><div class="rt"><b>★ ${p[4]}</b> (${p[5].toLocaleString()} reviews)</div><div class="pr">$${p[2]}${p[3]?`<s>$${p[3]}</s>`:''}</div><div class="row"><button class="btn btn-b" type="button" data-add>Add to cart</button><label class="cmp"><input type="checkbox" data-cmp="${k}">Compare</label></div></article>`;
document.getElementById('deals-grid').innerHTML=D.map((p,i)=>card(p,'d'+i)).join('');document.getElementById('best-grid').innerHTML=B.map((p,i)=>card(p,'b'+i)).join('');
let cart=0;document.addEventListener('click',e=>{if(e.target.matches('[data-add]')){cart++;document.getElementById('cc').textContent=cart;e.target.textContent='Added ✓';setTimeout(()=>e.target.textContent='Add to cart',1500)}});
document.addEventListener('change',e=>{if(!e.target.matches('[data-cmp]'))return;const on=[...document.querySelectorAll('[data-cmp]:checked')];if(on.length>3){e.target.checked=false;return}
const n=document.querySelectorAll('[data-cmp]:checked').length;document.getElementById('ctext').textContent=n+(n===1?' product':' products')+' to compare';document.getElementById('cbar').classList.toggle('show',n>0)});
const end=new Date();end.setHours(23,59,59,0);function tick(){let s=Math.max(0,Math.floor((end-new Date())/1000));const p=n=>String(n).padStart(2,'0');document.getElementById('h').textContent=p(Math.floor(s/3600));document.getElementById('m').textContent=p(Math.floor(s%3600/60));document.getElementById('sec').textContent=p(s%60)}tick();setInterval(tick,1000);
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
